const electron=require('electron'),{app,BrowserWindow}=electron,fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict')
const {HtmlVisualEditors,WORLD}=require('../../desktop/services/html-visual-editor.cjs')
const {EditorImages}=require('../../desktop/services/html-editor-images.cjs')
const {extractAttachmentText,inspectAttachmentPath}=require('../../desktop/services/attachments.cjs')
const {LocalHtmlPreview,localHtmlSource}=require('../../desktop/services/local-html-preview.cjs')
const out=path.resolve(__dirname,'../../qa-artifacts/html-editor');fs.mkdirSync(out,{recursive:true})
const work=fs.mkdtempSync(path.join(out,'run-'));app.setPath('userData',path.join(work,'profile'));app.disableHardwareAcceleration()
async function main(){
 await app.whenReady()
 const win=new BrowserWindow({show:false,width:1200,height:850,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false,offscreen:true}}),wc=win.webContents
 const js=code=>wc.executeJavaScriptInIsolatedWorld(WORLD,[{code:code+';true'}]),page=code=>wc.executeJavaScript(code)
 await win.loadURL('data:text/html,fixture')
 const png=await page(`(()=>{const c=document.createElement('canvas');c.width=16;c.height=8;const x=c.getContext('2d');x.fillStyle='red';x.fillRect(0,0,8,8);x.fillStyle='blue';x.fillRect(8,0,8,8);return c.toDataURL().split(',')[1]})()`)
 const originalImage=path.join(work,'input.png');fs.writeFileSync(originalImage,Buffer.from(png,'base64'))
 const file=path.join(work,'中文 report.html'),script=`document.querySelector('#chart').appendChild(document.createElement('canvas'));window.chartCount=1;`
 const source=`\ufeff<!doctype html>\r\n<html><head><meta charset="utf-8"><style>body{padding:40px;padding-top:320px}img{width:160px;height:80px}</style></head><body><h1 id="title">原始标题</h1><p id="description">正文</p><a id="link" href="https://example.com">链接</a><img id="photo" src="input.png" srcset="input.png 2x"><section id="chart"></section><script>${script}</script></body></html>`
 fs.writeFileSync(file,source);await win.loadFile(file)
 await js(`globalThis.originalAttach=Element.prototype.attachShadow;Element.prototype.attachShadow=function(options){const root=originalAttach.call(this,options);globalThis.editorRoot=root;return root}`)
 const fakeElectron={...electron,dialog:{showOpenDialog:async()=>({canceled:false,filePaths:[originalImage]})}}
 const editors=new HtmlVisualEditors(fakeElectron),state=await editors.start({conversationId:'a',file,view:{webContents:wc},roots:[work],workspace:work,window:win}),session=editors.get('a',state.sessionId)
 await js('Element.prototype.attachShadow=originalAttach');assert.ok(state.mapped.mapped>=4)
 await js(`__stableHtmlEditor.choose('#title');__stableHtmlEditor.run('text','新标题 & <安全>');__stableHtmlEditor.run('style',{name:'font-size',value:'32px'});__stableHtmlEditor.run('bold')`)
 await editors.flush(session)
 let saved=fs.readFileSync(file,'utf8');assert.ok(saved.includes('新标题 &amp; &lt;安全&gt;'));assert.ok(saved.includes(script));assert.equal(saved.includes('<canvas'),false);assert.ok(saved.includes('font-size:32px'))
 await js(`__stableHtmlEditor.run('undo');__stableHtmlEditor.run('undo');__stableHtmlEditor.run('undo')`);await editors.flush(session);assert.equal(fs.readFileSync(file,'utf8'),source)
 await js(`__stableHtmlEditor.run('redo');__stableHtmlEditor.run('redo');__stableHtmlEditor.run('redo')`);await editors.flush(session)
 // Real input events are collected while contenteditable stays focused; Esc reverses an autosaved edit.
 await js(`document.querySelector('#title').dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));document.querySelector('#title').textContent='输入自动保存';document.querySelector('#title').dispatchEvent(new Event('input',{bubbles:true}))`)
 await new Promise(r=>setTimeout(r,1000));assert.ok(fs.readFileSync(file,'utf8').includes('输入自动保存'))
 await js(`document.querySelector('#title').dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))`);await new Promise(r=>setTimeout(r,1000));assert.ok(fs.readFileSync(file,'utf8').includes('新标题 &amp; &lt;安全&gt;'))
 await js(`__stableHtmlEditor.choose('#link');editorRoot.querySelector('.linkURL').value='https://example.org/new?a=1&b=2';editorRoot.querySelector('.linkText').value='新链接';editorRoot.querySelector('[data-action=link]').click();__stableHtmlEditor.run('style',{name:'background-color',value:'#abcdef'});__stableHtmlEditor.run('style',{name:'border-color',value:'#123456'});__stableHtmlEditor.run('clearBackground');__stableHtmlEditor.run('clearBorder')`)
 await editors.flush(session);assert.ok(fs.readFileSync(file,'utf8').includes('https://example.org/new?a=1&amp;b=2'));assert.ok(fs.readFileSync(file,'utf8').includes('border-style:none'))
 await js(`__stableHtmlEditor.choose('#description');document.dispatchEvent(new KeyboardEvent('keydown',{key:'Delete',bubbles:true}))`);await editors.flush(session);assert.ok(!fs.readFileSync(file,'utf8').includes('id="description"'))
 await js(`document.dispatchEvent(new KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true}))`);await editors.flush(session);assert.ok(fs.readFileSync(file,'utf8').includes('id="description"'))
 fs.writeFileSync(path.join(out,'editor.png'),(await wc.capturePage()).toPNG())
 await js(`__stableHtmlEditor.choose('#photo');editorRoot.querySelector('[data-action=replace]').click()`)
 await editors.queue(session,()=>editors.tick(session));await editors.flush(session)
 const replaced=await page(`document.querySelector('#photo').getAttribute('src')`);assert.match(replaced,/\.assets\/images\/.*\.png$/);assert.ok(fs.existsSync(path.resolve(work,decodeURIComponent(replaced))));assert.equal(await page(`document.querySelector('#photo').hasAttribute('srcset')`),false)
 await js(`editorRoot.querySelector('[data-action=crop]').click()`);await editors.queue(session,()=>editors.tick(session))
 const filesBeforeCancel=fs.readdirSync(session.images.directory).length
 await js(`editorRoot.querySelector('.crop .cancel').click()`);assert.equal(fs.readdirSync(session.images.directory).length,filesBeforeCancel)
 await js(`editorRoot.querySelector('[data-action=crop]').click()`);await editors.queue(session,()=>editors.tick(session))
 fs.writeFileSync(path.join(out,'crop.png'),(await wc.capturePage()).toPNG())
 await js(`for(const [name,value]of Object.entries({x:8,y:0,w:8,h:8})){const input=editorRoot.querySelector('.crop input[name='+name+']');input.value=value;input.dispatchEvent(new Event('change'))}editorRoot.querySelector('.crop .confirm').click()`)
 await editors.queue(session,()=>editors.tick(session));await editors.flush(session)
 const cropped=await page(`document.querySelector('#photo').getAttribute('src')`);assert.notEqual(cropped,replaced)
 const cropFile=path.resolve(work,decodeURIComponent(cropped)),native=electron.nativeImage.createFromPath(cropFile);assert.deepEqual(native.getSize(),{width:8,height:8})
 const pixel=await page(`(async()=>{const i=new Image();i.src=${JSON.stringify(cropped)};await i.decode();const c=document.createElement('canvas');c.width=c.height=8;const x=c.getContext('2d');x.drawImage(i,0,0);return [...x.getImageData(4,4,1,1).data]})()`);assert.deepEqual(pixel,[0,0,255,255])
 assert.ok(fs.existsSync(path.resolve(work,decodeURIComponent(replaced))));const imageService=new EditorImages(electron,file,[work]);const origin=await imageService.original(cropped);assert.equal(origin.width,16);assert.equal(origin.height,8)
 const orientedJpeg=await page(`(()=>{const c=document.createElement('canvas');c.width=16;c.height=8;return c.toDataURL('image/jpeg').split(',')[1]})()`);const jpg=Buffer.from(orientedJpeg,'base64'),exif=Buffer.from('ffe1002245786966000049492a0008000000010012010300010000000600000000000000','hex');const rotated=await imageService.process(Buffer.concat([jpg.subarray(0,2),exif,jpg.subarray(2)]));assert.equal(rotated.width,8);assert.equal(rotated.height,16)
 await js(`__stableHtmlEditor.run('undo')`);await editors.flush(session);assert.ok(fs.readFileSync(file,'utf8').includes(replaced));await js(`__stableHtmlEditor.run('redo')`);await editors.flush(session)
 await js(`__stableHtmlEditor.choose('#title');document.querySelector('#description').dispatchEvent(new MouseEvent('click',{bubbles:true,shiftKey:true}));editorRoot.querySelector('.ai').value='同时调整这两个区域';editorRoot.querySelector('.ai').dispatchEvent(new Event('input'));location.hash='s2';editorRoot.querySelector('[data-action=draft]').click()`)
 await editors.queue(session,()=>editors.tick(session));const delivery=(await editors.poll('a',state.sessionId)).deliveries[0];assert.equal(delivery.attachments.length,2);assert.equal(delivery.send,false);assert.equal((await editors.poll('a',state.sessionId)).deliveries.length,1);editors.acknowledge('a',state.sessionId,delivery.id);assert.equal((await editors.poll('a',state.sessionId)).deliveries.length,0)
 assert.equal(delivery.attachments[0].path,file);assert.equal(delivery.prompt,'同时调整这两个区域');assert.equal(delivery.attachments[0].type,'html');const selectionSize=electron.nativeImage.createFromPath(delivery.attachments[1].path).getSize();assert.ok(selectionSize.height<250,JSON.stringify(selectionSize))
 const context=editors.contextForAttachment('a',delivery.attachments[1].path,work);assert.ok(context.includes(file));assert.ok(context.includes('nth-of-type'));assert.equal(inspectAttachmentPath(delivery.attachments[1].path).type,'png');assert.ok(!fs.existsSync(path.join(path.dirname(delivery.attachments[1].path),'选区.md')));assert.throws(()=>editors.contextForAttachment('b',delivery.attachments[1].path,work),/不属于/)
 assert.throws(()=>editors.get('b',state.sessionId),/失效/)
 const beforeConflict=fs.readFileSync(file,'utf8');await js(`__stableHtmlEditor.choose('#title');__stableHtmlEditor.run('text','不要覆盖外部')`);fs.writeFileSync(file,beforeConflict+'<!-- external -->');await assert.rejects(editors.flush(session),/修改/);assert.ok(fs.readFileSync(file,'utf8').endsWith('<!-- external -->'));assert.ok(fs.existsSync(session.recovery))
 const exported=path.join(work,'copy.html');await editors.export(session,exported);assert.ok(fs.readFileSync(exported,'utf8').includes('copy.assets/images/'));assert.ok(fs.existsSync(path.join(work,'copy.assets','images',path.basename(cropFile))))
 const exportedImages=new EditorImages(electron,exported,[work]);assert.equal((await exportedImages.original(cropped.replace(encodeURIComponent(session.images.folder),'copy.assets'))).width,16)
 await editors.stop('a',state.sessionId,{discard:true});await win.loadFile(exported);assert.equal(await page(`document.querySelectorAll('#chart canvas').length`),1);assert.ok(await page(`(async()=>{await document.querySelector('#photo').decode();return document.querySelector('#photo').naturalWidth===8})()`))
 // Simulate process loss after journal capture, then recover through the same start path.
 const crashEditors=new HtmlVisualEditors({...fakeElectron,dialog:{...fakeElectron.dialog,showMessageBox:async()=>({response:1})}})
 const crashState=await crashEditors.start({conversationId:'recovery',file:exported,view:{webContents:wc},roots:[work],workspace:work,window:win}),crashSession=crashEditors.get('recovery',crashState.sessionId)
 await js(`__stableHtmlEditor.choose('#title');__stableHtmlEditor.run('text','恢复后的标题')`);await crashEditors.queue(crashSession,()=>crashEditors.collect(crashSession));clearInterval(crashSession.timer);await crashEditors.call(crashSession,'dispose');wc.removeListener('will-navigate',crashSession.guard);crashEditors.sessions.delete(crashSession.id)
 assert.ok(fs.existsSync(crashSession.recovery));await win.loadFile(exported)
 const restored=await crashEditors.start({conversationId:'recovery',file:exported,view:{webContents:wc},roots:[work],workspace:work,window:win});assert.ok(fs.readFileSync(exported,'utf8').includes('恢复后的标题'));assert.equal(fs.existsSync(crashSession.recovery),false);await crashEditors.stop('recovery',restored.sessionId)
 await assert.rejects(imageService.process(Buffer.from('not an image')),/图片/);assert.throws(()=>imageService.read('https://example.com/a.png'),/本地/)
 const server=new LocalHtmlPreview([work]),url=await server.open(exported);assert.equal(localHtmlSource(url),exported);server.dispose();assert.equal(localHtmlSource(url),exported)
 fs.writeFileSync(path.join(out,'result.json'),JSON.stringify({passed:true,work,checks:['source preservation','typing autosave and Escape','undo redo','local replace','local crop blue pixels 8x8','crop cancellation','EXIF orientation','crash draft recovery','original retained across sessions','multi target AI and image attachment','conversation isolation','external conflict recovery','export resources','reload chart once','local URL provenance']},null,2))
 fs.writeFileSync(path.join(out,'saved-report.png'),(await wc.capturePage()).toPNG());win.destroy();console.log('HTML_VISUAL_EDITOR_PASSED');app.exit(0)
}
main().catch(e=>{console.error(e.stack);app.exit(1)})
